package com.franco.desco.adapter.in.web.sanitation;import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.sanitation.*;import com.franco.desco.application.sanitation.port.in.SanitationUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;
@RestController@RequestMapping("/api/v1/sanidad")@Tag(name="Sanidad vegetal",description="Casos fitosanitarios, tratamientos, seguimientos y cierre.")@SecurityRequirement(name=OpenApiConstants.BEARER_AUTH)@Validated public class SanitationController{private final SanitationUseCase u;private final SanitationWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public SanitationController(SanitationUseCase u,SanitationWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping@PreAuthorize("@permissionGuard.has(authentication,'SANIDAD_LISTAR')")@Operation(operationId="sanidadListar",summary="Listar casos fitosanitarios")public ResponseEntity<ApiResponse<PageResponse<SanitationResponses.Summary>>>list(@RequestParam(required=false)String estadoCaso,@RequestParam(required=false)String severidad,@RequestParam(required=false)Long predioId,@RequestParam(required=false)Long socioId,@RequestParam(required=false)Integer tipoProblemaId,@RequestParam(required=false)LocalDate fechaDesde,@RequestParam(required=false)LocalDate fechaHasta,@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(200)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.list(map.list(pagina,tamano,estadoCaso,severidad,predioId,socioId,tipoProblemaId,fechaDesde,fechaHasta),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @GetMapping("/{id}")@PreAuthorize("@permissionGuard.has(authentication,'SANIDAD_VER')")@Operation(operationId="sanidadVer",summary="Ver detalle completo del caso")public ResponseEntity<ApiResponse<SanitationResponses.Detail>>get(@PathVariable Long id,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.get(new SanitationCommands.Get(id),ids.resolve(a),meta.resolve(r)),r,map::response);}
 @PostMapping@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'SANIDAD_CREAR')")@Operation(operationId="sanidadCrear",summary="Registrar caso fitosanitario")public ResponseEntity<ApiResponse<SanitationResponses.Created>>create(@Valid@RequestBody SanitationRequests.Create q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.create(new SanitationCommands.Create(q.parcelaCultivoId(),q.tipoProblemaId(),q.visitaDeteccionId(),q.fechaDeteccion(),q.plantasAfectadas(),q.cantidadEstimada(),q.severidad(),q.observacion()),ids.resolve(a),meta.resolve(r)),r,SanitationResponses.Created::new);}
 @PutMapping("/{id}")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'SANIDAD_EDITAR')")@Operation(operationId="sanidadEditar",summary="Editar caso fitosanitario")public ResponseEntity<ApiResponse<Void>>update(@PathVariable Long id,@Valid@RequestBody SanitationRequests.Update q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.update(new SanitationCommands.Update(id,q.tipoProblemaId(),q.plantasAfectadas(),q.cantidadEstimada(),q.severidad(),q.observacion()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/estado")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'SANIDAD_EDITAR')")@Operation(operationId="sanidadCambiarEstado",summary="Ejecutar transición sanitaria",description="El PA valida la transición permitida; Java no implementa la máquina de estados.")public ResponseEntity<ApiResponse<Void>>state(@PathVariable Long id,@Valid@RequestBody SanitationRequests.ChangeState q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.changeState(new SanitationCommands.ChangeState(id,q.nuevoEstado(),q.motivo()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/cerrar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'SANIDAD_CONFIRMAR')")@Operation(operationId="sanidadCerrar",summary="Cerrar caso fitosanitario")public ResponseEntity<ApiResponse<Void>>close(@PathVariable Long id,@Valid@RequestBody SanitationRequests.Close q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.close(new SanitationCommands.Close(id,q.motivo()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/{id}/tratamientos")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'SANIDAD_CREAR')")@Operation(operationId="sanidadTratamientoRegistrar",summary="Registrar tratamiento")public ResponseEntity<ApiResponse<SanitationResponses.Created>>treatment(@PathVariable Long id,@Valid@RequestBody SanitationRequests.Treatment q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.addTreatment(new SanitationCommands.Treatment(id,q.visitaTecnicaId(),q.responsableEmpleadoId(),q.fechaHora(),q.tratamiento(),q.producto(),q.dosis(),q.unidadDosis(),q.observacion()),ids.resolve(a),meta.resolve(r)),r,SanitationResponses.Created::new);}
 @PostMapping("/{id}/seguimientos")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'SANIDAD_CREAR')")@Operation(operationId="sanidadSeguimientoRegistrar",summary="Registrar seguimiento")public ResponseEntity<ApiResponse<SanitationResponses.Created>>follow(@PathVariable Long id,@Valid@RequestBody SanitationRequests.FollowUp q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.addFollowUp(new SanitationCommands.FollowUp(id,q.visitaTecnicaId(),q.fechaHora(),q.plantasAfectadas(),q.cantidadEstimada(),q.severidad(),q.resultado(),q.observacion()),ids.resolve(a),meta.resolve(r)),r,SanitationResponses.Created::new);}}
